import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";import{v as i}from"./chunks/assets.DMkeNHu3.js";var a=JSON.parse(`{"title":"Guide to Using the Schema Markup Editor","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/12-schema-editor.md","filePath":"02-consumer/12-schema-editor.md"}`),o={name:`02-consumer/12-schema-editor.md`};function s(n,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[e(`<h1 id="guide-to-using-the-schema-markup-editor" tabindex="-1">Guide to Using the Schema Markup Editor <a class="header-anchor" href="#guide-to-using-the-schema-markup-editor" aria-label="Permalink to “Guide to Using the Schema Markup Editor”">​</a></h1><h2 id="editor-introduction" tabindex="-1">Editor Introduction <a class="header-anchor" href="#editor-introduction" aria-label="Permalink to “Editor Introduction”">​</a></h2><p>The Schema Markup editor is used to define and edit structured data. You can use this editor to enter Schema code and, when needed, use replaceable variables to access information related to the content in question.</p><p>This editor can be used in different areas of the panel, such as products, posts, and users. <strong>The buttons and variables available in each editor may differ depending on the type of information in that area.</strong></p><p><img src="`+i+`" alt="Schema Markup editor" width="1335" height="413"></p><p><em>Figure 1 - Example of the Schema Markup editor in the products section. The buttons shown in this image are specific to this example and are not necessarily the same in other areas of the panel.</em></p><h2 id="editor-components" tabindex="-1">Editor Components <a class="header-anchor" href="#editor-components" aria-label="Permalink to “Editor Components”">​</a></h2><h3 id="_1-variable-insertion-buttons" tabindex="-1">1. Variable Insertion Buttons <a class="header-anchor" href="#_1-variable-insertion-buttons" aria-label="Permalink to “1. Variable Insertion Buttons”">​</a></h3><p>The buttons above the editor are used to insert variables that let you use information related to the current content in the Schema code.</p><p>The available variables depend on the entity type and the information available for it. For example, the editor for products may have buttons for the name, price, and image, while the users section may provide variables such as email.</p><p>Therefore, check the list of buttons in the editor you are using, and use the variables available in that section.</p><h3 id="_2-viewing-variable-hints" tabindex="-1">2. Viewing Variable Hints <a class="header-anchor" href="#_2-viewing-variable-hints" aria-label="Permalink to “2. Viewing Variable Hints”">​</a></h3><p>To view a variable&#39;s description or sample value, hover over its button. A short hint appears, showing information about that variable.</p><p>This hint helps you identify the variable&#39;s purpose before inserting it.</p><h3 id="_3-inserting-a-variable-into-the-code" tabindex="-1">3. Inserting a Variable into the Code <a class="header-anchor" href="#_3-inserting-a-variable-into-the-code" aria-label="Permalink to “3. Inserting a Variable into the Code”">​</a></h3><p>To add a variable to the code, click its corresponding button. How the variable is inserted depends on the text selection in the editor:</p><ul><li><strong>If some text is selected,</strong> the selected text is replaced with the corresponding variable.</li><li><strong>If no text is selected,</strong> the variable is inserted at the current cursor position.</li></ul><p>For example, if you click the <code>Name</code> button in the editor for products, the variable for the name is inserted into the code. The exact form of the variable and its replacement value depend on that editor&#39;s settings.</p><h3 id="_4-reset-button" tabindex="-1">4. Reset Button <a class="header-anchor" href="#_4-reset-button" aria-label="Permalink to “4. Reset Button”">​</a></h3><p>The <code>Reset</code> button is used to restore the editor to its initial state.</p><p>If you have changed the editor&#39;s content and want to restore its initial state, you can use this button.</p><p><strong>Important:</strong> Review the current content before using Reset; resetting may discard changes made in the editor.</p><h3 id="_5-syntax-option" tabindex="-1">5. Syntax Option <a class="header-anchor" href="#_5-syntax-option" aria-label="Permalink to “5. Syntax Option”">​</a></h3><p>The <code>Syntax</code> option is used to select the code syntax for the editor. In the example image, the selected value is <code>HTML</code>.</p><p>Set this option to match the format of the code you enter.</p><h3 id="_6-code-editing-area" tabindex="-1">6. Code Editing Area <a class="header-anchor" href="#_6-code-editing-area" aria-label="Permalink to “6. Code Editing Area”">​</a></h3><p>The main editing area is used to enter, view, and edit Schema Markup code.</p><p>You can enter the code directly in this area or use the buttons above the editor to insert the required variables in the appropriate locations.</p><p>You can enter multiple schemas in one editor, so this area is not limited to a single schema.</p><h2 id="example-of-using-variables" tabindex="-1">Example of Using Variables <a class="header-anchor" href="#example-of-using-variables" aria-label="Permalink to “Example of Using Variables”">​</a></h2><p>The following example shows a <code>Product</code> schema with the name and description specified using replaceable variables:</p><div class="language-html"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;application/ld+json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &quot;@context&quot;: &quot;https://schema.org&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &quot;@type&quot;: &quot;Product&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &quot;name&quot;: &quot;%name%&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &quot;description&quot;: &quot;%desc%&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &quot;offers&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;@type&quot;: &quot;Offer&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;price&quot;: &quot;12.99&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;priceCurrency&quot;: &quot;USD&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>In this example:</p><ul><li><code>%name%</code> is the variable for the name.</li><li><code>%desc%</code> is the variable for the description.</li><li>The value <code>12.99</code> is entered as a fixed value.</li><li>The value <code>USD</code> specifies the currency.</li></ul><p>When displayed, the system replaces the variables. As a result, the defined variables are replaced with values related to the content in question.</p><p><strong>This example is intended only to explain how to use variables.</strong> Select the Schema type, fields, and appropriate variables based on the entity and the information available in the relevant editor.</p><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Notes”">​</a></h2><ul><li>The list of buttons and variables is not the same in every Schema editor.</li><li>To learn about a variable, hover over its button and review the displayed hint.</li><li>If text is selected, clicking a variable button replaces the selected text; otherwise, the variable is inserted at the cursor position.</li><li>You can enter multiple schemas in one editor.</li><li>Check the editor&#39;s current content before using Reset.</li><li>The code structure and entered values must be compatible with the Schema type and the information for the content in question.</li></ul>`,38)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};